import sys
import traceback
from io import StringIO


def _test(expected, actual, call):
    try:
        assert actual == expected, f"{call} should return {expected}. Your code: {actual}"
        print(f"\u2713 passed: {call} \u2192 {expected}")
    except AssertionError as ae:
        print(f"\u2717 failed: {ae}")


class ComputeStatsTests:

    def __init__(self, module_name):
        self.module = module_name
        self.compute_stats = self.module.compute_stats

    def _run_and_capture(self, file):
        """Run compute_stats(file) and capture stdout as a single string."""
        old_stdout = sys.stdout
        buffer = StringIO()
        try:
            sys.stdout = buffer
            self.compute_stats(file)
        except Exception as e:
            sys.stdout = old_stdout
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())
            return None
        finally:
            sys.stdout = old_stdout
        return buffer.getvalue()

    def test_01_numbers(self, file):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        output = self._run_and_capture(file)
        if output is None:
            return
        expected = (
            "Count: 9\n"
            "Average: 52.0\n"
            "Min: 14\n"
            "Max: 100\n"
            "Median: 52\n"
        )
        _test(expected, output, f'compute_stats("{file}")')

    def test_02_numbers2(self, file):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        output = self._run_and_capture(file)
        if output is None:
            return
        expected = (
            "Count: 9\n"
            "Average: 3.111111111111111\n"
            "Min: -22\n"
            "Max: 25\n"
            "Median: 7\n"
        )
        _test(expected, output, f'compute_stats("{file}")')

    def test_03_numbers6(self, file):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        output = self._run_and_capture(file)
        if output is None:
            return
        expected = (
            "Count: 4\n"
            "Average: 2.75\n"
            "Min: -6\n"
            "Max: 13\n"
            "Median: 2.0\n"
        )
        _test(expected, output, f'compute_stats("{file}")')

    def test_04_numbers7(self, file):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        output = self._run_and_capture(file)
        if output is None:
            return
        expected = (
            "Count: 10000\n"
            "Average: 1235036.6857\n"
            "Min: -999840077\n"
            "Max: 999983481\n"
            "Median: -7103923.5\n"
        )
        _test(expected, output, f'compute_stats("{file}")')

    def test_all(self, file_numbers, file_numbers2, file_numbers6, file_numbers7):
        self.test_01_numbers(file_numbers)
        self.test_02_numbers2(file_numbers2)
        self.test_03_numbers6(file_numbers6)
        self.test_04_numbers7(file_numbers7)
